//go:build ignore

// Gen compiles shader.hlsl to DXBC with the system's d3dcompiler_47.dll
// and writes shaders.go, so that apps need no shader compiler. It runs on
// Windows: go generate ./internal/gpu/d3d11
package main

import (
	"bytes"
	"fmt"
	"go/format"
	"log"
	"os"
	"syscall"
	"unsafe"

	"github.com/egoist/mygo/internal/gpu"
)

func main() {
	src, err := os.ReadFile("shader.hlsl")
	if err != nil {
		log.Fatal(err)
	}
	compiler := syscall.NewLazyDLL("d3dcompiler_47.dll").NewProc("D3DCompile")
	compile := func(entry, target string) []byte {
		var blob, errs uintptr
		name, _ := syscall.BytePtrFromString("shader.hlsl")
		e, _ := syscall.BytePtrFromString(entry)
		t, _ := syscall.BytePtrFromString(target)
		// IEEE strictness avoids the native optimizer's stack overflow on
		// transformed coverage sampling while retaining level 3 optimization.
		const optimize3IEEE = 1<<15 | 1<<13
		hr, _, _ := compiler.Call(uintptr(unsafe.Pointer(&src[0])), uintptr(len(src)), uintptr(unsafe.Pointer(name)),
			0, 0, uintptr(unsafe.Pointer(e)), uintptr(unsafe.Pointer(t)), optimize3IEEE, 0,
			uintptr(unsafe.Pointer(&blob)), uintptr(unsafe.Pointer(&errs)))
		if int32(hr) < 0 {
			msg := "unknown error"
			if errs != 0 {
				msg = string(blobBytes(errs))
			}
			log.Fatalf("%s: %s", entry, msg)
		}
		return append([]byte(nil), blobBytes(blob)...)
	}
	var b bytes.Buffer
	fmt.Fprintf(&b, "// Code generated by gen.go from shader.hlsl; DO NOT EDIT.\n\n//go:build windows\n\npackage d3d11\n\n")
	fmt.Fprintf(&b, "// shaderSum is the SHA-256 of the shader.hlsl the shaders were compiled\n// from.\nconst shaderSum = %q\n\n", gpu.SourceSum(string(src)))
	for _, s := range []struct{ name, entry, target string }{{"vertexShader", "vs", "vs_4_0"}, {"pixelShader", "ps", "ps_4_0"},
		{"passVertexShader", "passvs", "vs_4_0"}, {"downShader", "downps", "ps_4_0"}, {"blurShader", "blurps", "ps_4_0"}} {
		code := compile(s.entry, s.target)
		fmt.Fprintf(&b, "var %s = []byte{", s.name)
		for i, c := range code {
			if i%16 == 0 {
				b.WriteString("\n\t")
			}
			fmt.Fprintf(&b, "0x%02x, ", c)
		}
		b.WriteString("\n}\n\n")
	}
	out, err := format.Source(b.Bytes())
	if err != nil {
		log.Fatal(err)
	}
	if err := os.WriteFile("shaders.go", out, 0o644); err != nil {
		log.Fatal(err)
	}
}

// blobBytes returns the contents of an ID3DBlob.
func blobBytes(blob uintptr) []byte {
	call := func(i int) uintptr {
		vtbl := *(*uintptr)(unsafe.Pointer(blob))
		fn := *(*uintptr)(unsafe.Pointer(vtbl + uintptr(i)*unsafe.Sizeof(uintptr(0))))
		r, _, _ := syscall.SyscallN(fn, blob)
		return r
	}
	p, n := call(3), call(4)
	return unsafe.Slice((*byte)(unsafe.Pointer(p)), n)
}
